p="/app/frontend/src/lib/i18n.js"; s=open(p).read()
s=s.replace('  { code: "ar", name: "العربية"','  { code: "ur", name: "اردو", flag: "🇵🇰", dir: "rtl" },\n  { code: "ar", name: "العربية"',1)
missing=[]
def sub(m):
    k=m.group(1)
    if k not in UR: missing.append(k); return m.group(0)
    return m.group(0)+', ur: "'+UR[k]+'"'
s=re.sub(r'^  ([a-z_0-9]+): \{ .*?bn: "[^"]*"(?= \})', sub, s, flags=re.M)
s=re.sub(r'(    bn: "[^"]*",\n)', lambda m: m.group(1)+'    ur: "'+UR["tagline"]+'",\n', s, count=1)
open(p,"w").write(s)
print("missing",missing,"ur count",s.count('ur: "'))
